module.exports = function(RED) {
    "use strict";

    const {Queue, Worker} = require("bullmq");

    function RedisConfigNode(config) {
        RED.nodes.createNode(this, config);
        const port = Number(config.port === undefined || config.port === "" ? 6379 : config.port);
        const db = Number(config.db === undefined || config.db === "" ? 0 : config.db);
        if (!config.host || !Number.isInteger(port) || port < 1 || port > 65535 || !Number.isInteger(db) || db < 0) {
            throw new Error("Invalid BullMQ Redis configuration");
        }
        this.connection = {
            host: config.host,
            port,
            db,
            ...(this.credentials?.username ? {username: this.credentials.username} : {}),
            ...(this.credentials?.password ? {password: this.credentials.password} : {}),
            ...(config.tls === true ? {tls: {}} : {})
        };
    }

    function getSettings(node, config) {
        const redis = RED.nodes.getNode(config.redis);
        if (!redis || !redis.connection) {
            node.status({fill: "red", shape: "ring", text: "Redis not configured"});
            node.error("BullMQ Redis server is not configured");
            return;
        }
        if (typeof config.queue !== "string" || !config.queue.trim()) {
            node.status({fill: "red", shape: "ring", text: "Queue not configured"});
            node.error("BullMQ queue name is required");
            return;
        }
        return {queue: config.queue.trim(), connection: redis.connection};
    }

    function BullMQOutNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        const settings = getSettings(node, config);
        if (!settings) {
            return;
        }
        const queue = new Queue(settings.queue, {
            connection: {...settings.connection, maxRetriesPerRequest: 1}
        });
        queue.on("error", error => node.error(error));
        node.on("input", async function(msg, send, done) {
            try {
                const jobName = config.jobName?.trim() || "message";
                const {_msgid, ...data} = msg;
                const job = await queue.add(jobName, JSON.parse(JSON.stringify(data)));
                msg.bullmq = {queue: settings.queue, jobId: job.id, name: job.name};
                send(msg);
                done();
            } catch (error) {
                done(error);
            }
        });
        node.on("close", function(done) {
            queue.close().then(() => done(), done);
        });
    }

    function BullMQInNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        const settings = getSettings(node, config);
        if (!settings) {
            return;
        }
        const concurrency = Number(config.concurrency === undefined || config.concurrency === "" ? 1 : config.concurrency);
        if (!Number.isSafeInteger(concurrency) || concurrency < 1) {
            node.status({fill: "red", shape: "ring", text: "Invalid concurrency"});
            node.error("BullMQ concurrency must be a positive integer");
            return;
        }
        const worker = new Worker(settings.queue, async job => {
            const msg = job.data && typeof job.data === "object" && !Array.isArray(job.data)
                ? {...job.data}
                : {payload: job.data};
            delete msg._msgid;
            msg.bullmq = {queue: settings.queue, jobId: job.id, name: job.name};
            node.send(msg);
        }, {connection: {...settings.connection, maxRetriesPerRequest: null}, concurrency});
        worker.on("error", error => {
            node.status({fill: "red", shape: "ring", text: "Redis error"});
            node.error(error);
        });
        worker.on("failed", (job, error) => node.error(error));
        node.on("close", function(done) {
            worker.close().then(() => done(), done);
        });
    }

    RED.nodes.registerType("bullmq redis", RedisConfigNode, {
        credentials: {username: {type: "text"}, password: {type: "password"}}
    });
    RED.nodes.registerType("bullmq out", BullMQOutNode);
    RED.nodes.registerType("bullmq in", BullMQInNode);
};
